/*
 * Auxiliary logic test for CVE-2019-9445 / f2fs_fill_dentries namelen bound.
 *
 * This is NOT a kernel build. It independently reproduces the exact boolean
 * expression added by the reference fix and evaluates it for the positive,
 * boundary and vulnerability-triggering negative cases using the real macro
 * definitions from the target tree:
 *   include/linux/f2fs_fs.h:170  #define F2FS_NAME_LEN 255
 *   include/linux/f2fs_fs.h:439  #define F2FS_SLOT_LEN 8
 *   include/linux/f2fs_fs.h:442  #define GET_DENTRY_SLOTS(x) ((x + F2FS_SLOT_LEN - 1) >> F2FS_SLOT_LEN_BITS)
 *
 * `d->max` is taken as NR_DENTRY_IN_BLOCK = 214 (4K block, target fs/f2fs/f2fs.h).
 */
#include <stdio.h>

#define F2FS_NAME_LEN       255
#define F2FS_SLOT_LEN       8
#define F2FS_SLOT_LEN_BITS  3
#define GET_DENTRY_SLOTS(x) ((x + F2FS_SLOT_LEN - 1) >> F2FS_SLOT_LEN_BITS)
#define D_MAX               214

/* pre-fix target condition */
static int prefix_rejects(unsigned int bit_pos, unsigned int name_len)
{
	unsigned int pos = bit_pos + GET_DENTRY_SLOTS(name_len);
	return pos > D_MAX;
}

/* post-fix condition (candidate CU-001) */
static int postfix_rejects(unsigned int bit_pos, unsigned int name_len)
{
	unsigned int pos = bit_pos + GET_DENTRY_SLOTS(name_len);
	return pos > D_MAX || name_len > F2FS_NAME_LEN;
}

static int failures;

static void check(const char *label, unsigned int bit_pos, unsigned int name_len,
		  int expect_prefix, int expect_postfix)
{
	int pre = prefix_rejects(bit_pos, name_len);
	int post = postfix_rejects(bit_pos, name_len);
	int ok = (pre == expect_prefix) && (post == expect_postfix);
	printf("%-46s name_len=%u slots=%u bit_pos=%u pre=%d post=%d [%s]\n",
	       label, name_len, GET_DENTRY_SLOTS(name_len), bit_pos, pre, post,
	       ok ? "OK" : "FAIL");
	if (!ok)
		failures++;
}

int main(void)
{
	/* positive: legitimate entry, unchanged in both variants */
	check("positive legitimate name", 10, 200, 0, 0);
	/* boundary: exactly F2FS_NAME_LEN, still accepted */
	check("boundary name_len == 255", 180, 255, 0, 0);
	/* vulnerability: 256 > 255 but slots still inside d->max */
	check("negative name_len 256 within max", 180, 256, 0, 1);
	/* vulnerability: large corrupted name, advance still within max */
	check("negative name_len 300 within max", 10, 300, 0, 1);
	/* existing guard still fires for huge / out-of-range entries */
	check("existing guard huge name_len", 10, 65535, 1, 1);
	check("existing guard bit_pos overflow", 210, (D_MAX - 210 + 1) * F2FS_SLOT_LEN, 1, 1);

	if (failures) {
		printf("RESULT: %d failure(s)\n", failures);
		return 1;
	}
	printf("RESULT: all logic cases passed\n");
	return 0;
}

